import React, { useState, useEffect } from "react"
import axios from "axios"

const SearchResults = async ({members}) => {
    const [results, setResults] = useState(members.fullname)
    
    useEffect(() => {
        const fetchResults = async (value) => {
            try {
                const res = await axios.get(`http://localhost:8800/members?search=${searchTerm}`)
                setResults(res.data)
            } catch (error) {
                console.error("Error fetching search results: ", error)
            }
        }
    
        fetchResults()
    }, [results]) // dependencies on results (runs when "results" change)


    
}

export default SearchResults
